using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text.Json;
using RAWSelectionAssistant.Core.Services.Color;
using RAWSelectionAssistant.Core.Services.Color.PhotoWideV1;
using RAWSelectionAssistant.Core.Services.Projects;
record Req(string Method,string Roi,string Anchor,double Ev,double Strength,double ReferenceEv,string? Output=null,bool Metrics=true);
static class Program
{
 static double L(double r,double g,double b)=>.2126*r+.7152*g+.0722*b;static readonly JsonSerializerOptions Json=new(){PropertyNameCaseInsensitive=true};static readonly Dictionary<string,float[]> Files=new();static int Calls;static readonly Stopwatch Clock=Stopwatch.StartNew();
 static float[] Read(string path){if(Files.TryGetValue(path,out var f))return f;var b=File.ReadAllBytes(path);if(b.Length%12!=0)throw new InvalidDataException("RGB float length");var p=new float[b.Length/4];Buffer.BlockCopy(b,0,p,0,b.Length);if(p.Any(v=>!float.IsFinite(v)||v<0||v>1))throw new InvalidDataException("Frozen input domain");Files[path]=p;return p;}
 static double D(double v)=>v<=.04045?v/12.92:Math.Pow((v+.055)/1.055,2.4);static double Y(float[] v,int i)=>.2126*D(v[i])+.7152*D(v[i+1])+.0722*D(v[i+2]);
 static float[] Render(float[] src,Req r){float[] p;if(r.Method.StartsWith("post-")||r.Method=="legacy"){p=new float[src.Length];var exposure=new RenderedSrgbExposure(ExposureEv:r.Ev);for(int i=0;i<p.Length;i+=3){var v=exposure.Apply(new(src[i],src[i+1],src[i+2]));p[i]=(float)v.X;p[i+1]=(float)v.Y;p[i+2]=(float)v.Z;}if(r.Method=="legacy")return p;}else p=src;
 var d=new Dictionary<string,double>();var curve=r.Method=="post-curve";if(curve){d["rgb_count"]=5;for(int i=0;i<5;i++){d[$"rgb_x{i}"]=i/4d;d[$"rgb_y{i}"]=i==4?r.Strength:i/4d;}}else{d["exposure"]=r.Method.StartsWith("basic-")?r.Ev:0;d[r.Method.EndsWith("highlights")?"highlights":"whites"]=r.Strength;}
 using var input=new HighBitDepthImageBuffer(p.Length/3,1,p,"32f","sRGB");var n=new ColorAdjustmentStackNode(Guid.Parse("20261117-0000-0000-0000-000000000001"),curve?ColorStudioNodeType.Curve:ColorStudioNodeType.BasicTone,"Frozen fairness control",NumericParameters:d);using var o=ColorStudioToolProcessor.Apply(input,n);return o.Rgb32.ToArray();}
 static double HR(float[] o,float[] s,int ev){int w=(int)Math.Sqrt(s.Length/3),h=w;var yy=new double[w*h];var mm=new bool[w*h];for(int p=0;p<w*h;p++){int i=p*3;yy[p]=L(D(o[i]),D(o[i+1]),D(o[i+2]));mm[p]=Math.Max(D(s[i])*Math.Pow(2,ev),Math.Max(D(s[i+1])*Math.Pow(2,ev),D(s[i+2])*Math.Pow(2,ev)))>.75;}double sum=0;long n=0;for(int y=0;y<h;y++)for(int x=0;x<w;x++){int p=y*w+x;if(x+1<w&&mm[p]&&mm[p+1]){var d=yy[p+1]-yy[p];sum+=d*d;n++;}if(y+1<h&&mm[p]&&mm[p+w]){var d=yy[p+w]-yy[p];sum+=d*d;n++;}}return n==0?double.NaN:Math.Sqrt(sum/n);}static object Eval(Req r){Calls++;if(Calls>22000||Clock.Elapsed.TotalSeconds>600)throw new InvalidOperationException("Frozen comparison call/time cap");var src=Read(r.Roi);var output=Render(src,r);if(r.Output is{} file){Directory.CreateDirectory(Path.GetDirectoryName(file)!);var bytes=MemoryMarshal.AsBytes(output.AsSpan());using var f=new FileStream(file,FileMode.CreateNew,FileAccess.Write,FileShare.None);f.Write(bytes);}
 if(!r.Metrics)return new{ok=true,calls=Calls,output=r.Output};var anchor=Read(r.Anchor);var ao=Render(anchor,r);double ms=0,hs=0;int mn=0,hn=0;double gain=Math.Pow(2,r.ReferenceEv);for(int i=0;i<anchor.Length;i+=3){var y=Y(anchor,i);if(y>=.03&&y<=.35){ms+=Y(ao,i);mn++;}}for(int i=0;i<src.Length;i+=3){if(Math.Max(D(src[i]),Math.Max(D(src[i+1]),D(src[i+2])))*gain>.75){hs+=Y(output,i);hn++;}}return new{ok=true,calls=Calls,mid=mn>=16?(double?)(ms/mn):null,high=hn>=16?(double?)(hs/hn):null,highRms=HR(output,src,(int)Math.Round(r.ReferenceEv)),midPixels=mn,highPixels=hn};}
 static int Main(){string? line;try{while((line=Console.ReadLine())is not null){if(line=="QUIT")break;try{var r=JsonSerializer.Deserialize<Req>(line,Json)!;Console.WriteLine(JsonSerializer.Serialize(Eval(r)));}catch(Exception e){Console.WriteLine(JsonSerializer.Serialize(new{ok=false,error=e.ToString()}));return 2;}}var modules=Process.GetCurrentProcess().Modules.Cast<ProcessModule>().Select(x=>x.ModuleName).ToArray();if(modules.Any(x=>x.Equals("raw_r.dll",StringComparison.OrdinalIgnoreCase)||x.Equals("libraw.dll",StringComparison.OrdinalIgnoreCase)))return 3;Console.Error.WriteLine(JsonSerializer.Serialize(new{calls=Calls,elapsedMs=Clock.Elapsed.TotalMilliseconds,rawNativeLoaded=false}));return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
